import { Actions } from '@app/actions/shared';
import {
  updateAllQualityMenuItems,
  revertUpdateAllQualityMenuItems,
} from './utils/qualityMenuUtils';
import { YTB_SCRIPT_SOURCE, YTbPlayerActions } from './types/player';
import { isMessageOfType } from '@app/messages/shared';
import { browser_api } from '@app/browser_api';
import { detectBrowser } from '@app/utils/detectBrowser';
import {
  ConnectionState,
  PaymentStatus,
} from '@app/storage/local/types/persistentTypes';
import { Feature } from '@app/features/types/Feature';
import { getLocalStorageData } from '@app/storage/local/shared';
import { LocalStorageKey } from '@app/storage/local/types/sharedTypes';
import { shouldShowMedia } from '@content/utils/shouldShowMedia';
import { logger } from '@utils/logger';

if (
  window?.location?.host?.includes('youtube.com') ||
  window?.location?.host?.includes('youtu.be')
) {
  logger.warn('[Ytb-quality-restriction] Observer initialized');

  let isRestrictionMessageSent = false;
  let isRestrictionEnabled: boolean = false;
  let configsBaseUrl: string | undefined;
  let status: PaymentStatus | undefined;
  let connectionState: ConnectionState | undefined;
  let isFeatureEnabled: boolean = false;
  let observer: MutationObserver | null = null;
  let mediaMaxVersionChrome: string | undefined;
  let mediaMaxVersionFirefox: string | undefined;

  async function initFeatures() {
    try {
      const { featureStoreV2, metaApiData } = await getLocalStorageData([
        LocalStorageKey.FeatureStoreV2,
        LocalStorageKey.MetaApiData,
      ]);

      if (metaApiData) {
        mediaMaxVersionChrome = metaApiData.mediaMaxVersionChrome;
        mediaMaxVersionFirefox = metaApiData.mediaMaxVersionFirefox;
      }

      if (featureStoreV2) {
        const configValue: boolean =
          !!featureStoreV2.featuresList?.[Feature.YoutubeRestrictionQuality];
        const localValue: boolean | undefined =
          featureStoreV2.featuresListLocal?.[Feature.YoutubeRestrictionQuality];
        updateFeatureFlag(configValue, localValue);
      }
    } catch (error) {
      logger.error(
        '[Ytb-quality-restriction] Error initializing features:',
        error,
      );
    }
  }

  function updateFeatureFlag(
    configValue: boolean,
    localValue: boolean | undefined,
  ) {
    isFeatureEnabled = localValue ?? configValue;
    setRestrictionOnMenuByStatusAndConnection();
  }

  function observerCallback() {
    if (isRestrictionEnabled) {
      updateAllQualityMenuItems(configsBaseUrl);
      if (!isRestrictionMessageSent) {
        sendRestrictionQualityMessageToYtbPlayer();
      }
    } else {
      revertUpdateAllQualityMenuItems();
      try {
        window?.postMessage(
          {
            source: YTB_SCRIPT_SOURCE,
            type: YTbPlayerActions['stop-restrict-quality'],
          },
          '*',
        );
      } catch (error) {
        logger.error(
          '[Ytb-quality-restriction] Error sending message "stop-restrict-quality" to Ytb player:',
          error,
        );
      }
      isRestrictionMessageSent = false;
    }
  }

  function sendRestrictionQualityMessageToYtbPlayer() {
    if (isRestrictionEnabled) {
      try {
        window?.postMessage(
          {
            source: YTB_SCRIPT_SOURCE,
            type: YTbPlayerActions['set-quality'],
          },
          '*',
        );
      } catch (error) {
        logger.error(
          '[Ytb-quality-restriction] Error sending message "set-quality" to Ytb player:',
          error,
        );
      }
    }
    isRestrictionMessageSent = true;
  }

  function setRestrictionOnMenuByStatusAndConnection() {
    const isFirefox = detectBrowser() === 'firefox';
    const currentVersion =
      browser_api.runtime.getManifest()?.version || '0.0.0';
    const shouldShow = shouldShowMedia(
      currentVersion,
      isFirefox,
      mediaMaxVersionChrome,
      mediaMaxVersionFirefox,
    );

    isRestrictionEnabled =
      isFeatureEnabled &&
      status === 'Free' &&
      connectionState === 'connected' &&
      shouldShow;
    observerCallback();
  }

  if (!observer) {
    observer = new MutationObserver(observerCallback);
    observer.observe(document.body, {
      childList: true,
      subtree: true,
    });
    logger.warn('[Ytb-quality-restriction] MutationObserver initialized');
  }

  try {
    void initFeatures();

    browser_api.runtime.onMessage.addListener((message: unknown) => {
      if (isMessageOfType(message, Actions.ConfigsBaseUrl)) {
        configsBaseUrl = message.payload.configsBaseUrl;
      }

      if (isMessageOfType(message, Actions.UserStatusChanged)) {
        status = message.payload.status;
        setRestrictionOnMenuByStatusAndConnection();
      }

      if (isMessageOfType(message, Actions.ConnectionStateChanged)) {
        connectionState = message.payload.connectionState;
        setRestrictionOnMenuByStatusAndConnection();
      }

      if (isMessageOfType(message, Actions.FeatureStoreV2Changed)) {
        const { featuresList, featuresListLocal } =
          message.payload.featureStore;

        const configValue: boolean =
          !!featuresList?.[Feature.YoutubeRestrictionQuality];
        const localValue: boolean | undefined =
          featuresListLocal?.[Feature.YoutubeRestrictionQuality];
        updateFeatureFlag(configValue, localValue);
      }
    });
  } catch (error) {
    logger.error(
      '[Ytb-quality-restriction] Error adding listener to runtime message:',
      error,
    );
  }
} else {
  logger.warn('[Ytb-quality-restriction] Not a YouTube tab, script exiting');
}
